namespace UniversityCourseCatalog.Models;

public class Department
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public string Id { get; set; } = string.Empty;
    public string DepartmentId { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public string CourseId { get; set; } = string.Empty;
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = "math", Name = "Mathematics", Description = "Pure and applied mathematics including analysis, algebra, and statistics." },
        new() { Id = "eng", Name = "English", Description = "Literature, writing, and linguistic studies." },
        new() { Id = "phys", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = "hist", Name = "History", Description = "Exploration of past events, societies, and civilizations." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = "CS101", DepartmentId = "cs", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Covers variables, control flow, data structures, and object-oriented principles.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a Ph.D. from MIT and has published extensively on programming pedagogy.", IsFeatured = true },
        new() { Id = "CS201", DepartmentId = "cs", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm optimization and competitive programming. He previously worked at Google Research before joining academia." },
        new() { Id = "CS301", DepartmentId = "cs", Title = "Database Systems", Description = "Relational database design, SQL, transaction processing, and introduction to NoSQL systems.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Prof. Maria Rodriguez", InstructorBio = "Prof. Rodriguez has contributed to several open-source database projects and consults for enterprise data architecture.", IsFeatured = true },
        new() { Id = "MATH101", DepartmentId = "math", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator who has taught calculus for over 20 years. He authored the widely-used textbook 'Calculus Made Clear'." },
        new() { Id = "MATH201", DepartmentId = "math", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, and eigenvalues with applications.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson researches applied linear algebra and machine learning. She holds joint appointments in Mathematics and Data Science.", IsFeatured = true },
        new() { Id = "ENG101", DepartmentId = "eng", Title = "Composition & Rhetoric", Description = "Develop clear, persuasive writing skills through essays, research papers, and peer review workshops.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. David Thompson", InstructorBio = "Prof. Thompson is a published author and writing coach with a focus on academic and professional communication." },
        new() { Id = "ENG205", DepartmentId = "eng", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, including poetry, fiction, and essays.", Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", InstructorName = "Dr. Lisa Martinez", InstructorBio = "Dr. Martinez specializes in 20th-century American fiction and has published three books on the Harlem Renaissance.", IsFeatured = true },
        new() { Id = "PHYS101", DepartmentId = "phys", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:00 PM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is an experimental physicist whose research focuses on fluid dynamics. He brings real-world lab experience into the classroom." },
        new() { Id = "PHYS202", DepartmentId = "phys", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 9:00–10:15 AM + Fri Lab 10:00 AM–12:00 PM", InstructorName = "Dr. Nina Patel", InstructorBio = "Dr. Patel's research in photonics has been recognized with multiple national awards. She is passionate about making physics accessible." },
        new() { Id = "HIST101", DepartmentId = "hist", Title = "World History to 1500", Description = "Survey of major civilizations, cultural exchanges, and turning points in human history from antiquity to the early modern period.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", InstructorName = "Dr. Michael Brown", InstructorBio = "Dr. Brown is an archaeologist and historian who has led excavations in the Mediterranean and Middle East." },
        new() { Id = "HIST250", DepartmentId = "hist", Title = "Modern European History", Description = "Political, social, and cultural developments in Europe from the Enlightenment through the 21st century.", Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", InstructorName = "Prof. Catherine Dubois", InstructorBio = "Prof. Dubois specializes in French Revolution studies and has been a visiting scholar at the Sorbonne.", IsFeatured = true },
    ];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) =>
        _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? departmentId = null, string? searchTerm = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
        {
            query = query.Where(c => c.DepartmentId == departmentId);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Id.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(string id) =>
        _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In production, this would persist to a database
        return !string.IsNullOrWhiteSpace(request.StudentName) &&
               !string.IsNullOrWhiteSpace(request.StudentId) &&
               !string.IsNullOrWhiteSpace(request.CourseId) &&
               _courses.Any(c => c.Id == request.CourseId);
    }
}

